package main

import (
	"fmt"
	"strings"
)

func add(a, b int) int {
	hint := "marker <<<<<<< SKIP inside string is inert"
	head := "<<<<<<< HEAD from a git conflict is plain content"
	tail := ">>>>>>> SKIP with right brackets is plain content"
	_ = strings.ToUpper(hint + head + tail)
	return a + b
}

func main() {
	fmt.Println(add(2, 3))
}
